const deliveryNativeFiles={"Dockerfile.mq-client": "FROM python@sha256:e064671ca452259bab50e8e2c7bd896e39e9a343bb06ca25234adf6fe18d0fc7\nRUN pip install --no-cache-dir pika==1.3.2\nWORKDIR /work\nCOPY mq_client.py /work/mq_client.py\nCMD [\"python\", \"-c\", \"import time; time.sleep(600)\"]\n", "README.md": "# 三个独立实验：运输确认、状态管理、持续调谐\n\n先分别读C5.2、C6.2和C6.3的对象与机制，再选一项运行。它们共用下载包，不要求依次运行，不连接生产或付费云。\n\n## 消息投递\n\nPython 3.9+标准库、本地Linux Docker引擎。客户端镜像按Dockerfile安装Pika 1.3.2，代理固定RabbitMQ 4.4.0，下载镜像和依赖需联网。\n\n```sh\npython3 -B mq_delivery.py --output runs/mq-record.json\n```\n\n只创建随机命名容器、内部网络、专用卷和客户端镜像，不发布宿主端口。公开固定凭据只适用于这组临时隔离夹具。结束删除自有资源，不清理其他Docker对象。环境只接受本地Unix socket上下文，不接受DOCKER_HOST远端地址。\n\n核对三份事实：发布确认、运输ACK、SQLite实际效果。真实子进程提交report-27=37后被SIGKILL，重投和新消息标识再发布都保持一次效果；先ACK再写业务的负例队列0、效果0，被验收拒绝。错误通道确认返回406。订阅prefetch=1时先只交付1条，basic.get仍可拉2条未确认消息。代理容器重启后从同一专用卷读回持久消息amount=7。\n\n这是AMQP 0-9-1/RabbitMQ实测，不是SQS、Lambda、节点永久丢失或多副本高可用测试。\n\n## Terraform状态\n\n准备官方Terraform 1.13.0（https://releases.hashicorp.com/terraform/1.13.0/），并核对官方SHA256SUMS。实验init下载官方hashicorp/local 2.5.3，仅管理自己的临时文件。\n\n```sh\nterraform version\npython3 -B terraform_state.py --output runs/terraform-record.json\n```\n\n不要求Docker。程序使用临时目录和专用CLI配置。一个apply停在受控执行钩子并保持local状态锁，第二个plan被拒绝；放行后正常完成。实际文件alpha被改outside后，关闭刷新的计划退出0；refresh-only应用后state不再有旧文件绑定，磁盘outside保留；普通修复再变alpha。blue/green工作空间有不同状态身份却指同一路径，green写beta后blue缓存计划仍可退出0。\n\n状态锁不阻止其他状态或人工修改同一实物。这里没有云provider、远端backend或高可用锁验证。不要在业务目录直接替换脚本中的隔离机制。\n\n## GitOps真实调谐\n\nPython 3.9+、本地Linux Docker、kubectl与kind v0.33.0。kind安装见 https://kind.sigs.k8s.io/docs/user/quick-start/ 。程序使用固定摘要的Kubernetes v1.35.8节点镜像，安装官方Argo CD Core v3.6.1，需下载镜像及公开源。\n\n```sh\npython3 -B gitops_reconcile.py --output runs/gitops-record.json\n```\n\n创建自己的kind集群；每次kubectl显式指定临时kubeconfig/context，结束只删自己的集群。Application固定读取本站公开仓库和gitops-revisions.json里的三个完整提交，AppProject限制源、命名空间和资源种类；不使用用户私有Git凭据，不对外发布管理界面。\n\n三份修订：v1配置/模板；只改配置v2并移除旧ConfigMap；修改模板注解触发v2新Pod。实际核对手改2副本、自愈恢复1；prune关闭保留受管旧配置，开启后删除它，未受管对象保留。配置v2且Synced/Healthy时旧Pod仍HTTP v1；替换模板后新UID、HTTP v2。再改变期望回到v1，重新验收配置与响应。此处不是调用Argo rollback API。\n\nkind是单机容器节点。这里验证真实控制器和服务请求，不证明云CNI/CSI、生产性能、高可用或任意数据库迁移可回退。\n\n## 已有执行证据\n\nvalidation.json保存本轮成功Linux CI的原始程序记录、精确源码摘要、固定Git修订及清单内容，和自己新跑的runs报告分开。首轮消息就绪检测失败后补了诊断和执行边界，未通过运行不计作完成证据。后续修改程序应重新运行相关原生环境并生成新记录。\n", "gitops-app/configmap.json": "{\n  \"apiVersion\": \"v1\",\n  \"kind\": \"ConfigMap\",\n  \"metadata\": {\n    \"name\": \"guide-version\"\n  },\n  \"data\": {\n    \"version\": \"v2\"\n  }\n}\n", "gitops-app/deployment.json": "{\n  \"apiVersion\": \"apps/v1\",\n  \"kind\": \"Deployment\",\n  \"metadata\": {\n    \"name\": \"guide-web\"\n  },\n  \"spec\": {\n    \"replicas\": 1,\n    \"selector\": {\n      \"matchLabels\": {\n        \"app\": \"guide-web\"\n      }\n    },\n    \"template\": {\n      \"metadata\": {\n        \"labels\": {\n          \"app\": \"guide-web\"\n        },\n        \"annotations\": {\n          \"guide/revision\": \"v2\"\n        }\n      },\n      \"spec\": {\n        \"containers\": [\n          {\n            \"name\": \"web\",\n            \"image\": \"python@sha256:e064671ca452259bab50e8e2c7bd896e39e9a343bb06ca25234adf6fe18d0fc7\",\n            \"command\": [\n              \"python\",\n              \"-u\",\n              \"-c\",\n              \"import json,os,socket\\nfrom http.server import BaseHTTPRequestHandler,HTTPServer\\nclass H(BaseHTTPRequestHandler):\\n def do_GET(self):\\n  b=json.dumps({\\\"version\\\":os.environ[\\\"BUSINESS_VERSION\\\"],\\\"pod\\\":socket.gethostname()}).encode(); self.send_response(200); self.send_header(\\\"Content-Length\\\",str(len(b))); self.end_headers(); self.wfile.write(b)\\n def log_message(self,*args): pass\\nHTTPServer((\\\"0.0.0.0\\\",8080),H).serve_forever()\"\n            ],\n            \"env\": [\n              {\n                \"name\": \"BUSINESS_VERSION\",\n                \"valueFrom\": {\n                  \"configMapKeyRef\": {\n                    \"name\": \"guide-version\",\n                    \"key\": \"version\"\n                  }\n                }\n              }\n            ],\n            \"ports\": [\n              {\n                \"containerPort\": 8080\n              }\n            ],\n            \"readinessProbe\": {\n              \"httpGet\": {\n                \"path\": \"/version\",\n                \"port\": 8080\n              }\n            },\n            \"resources\": {\n              \"requests\": {\n                \"cpu\": \"25m\",\n                \"memory\": \"32Mi\"\n              },\n              \"limits\": {\n                \"cpu\": \"200m\",\n                \"memory\": \"128Mi\"\n              }\n            },\n            \"securityContext\": {\n              \"allowPrivilegeEscalation\": false,\n              \"readOnlyRootFilesystem\": true,\n              \"runAsNonRoot\": true,\n              \"runAsUser\": 10001,\n              \"capabilities\": {\n                \"drop\": [\n                  \"ALL\"\n                ]\n              }\n            }\n          }\n        ]\n      }\n    }\n  }\n}\n", "gitops-app/service.json": "{\n  \"apiVersion\": \"v1\",\n  \"kind\": \"Service\",\n  \"metadata\": {\n    \"name\": \"guide-web\"\n  },\n  \"spec\": {\n    \"selector\": {\n      \"app\": \"guide-web\"\n    },\n    \"ports\": [\n      {\n        \"port\": 8080,\n        \"targetPort\": 8080\n      }\n    ]\n  }\n}\n", "gitops-revisions.json": "{\n  \"repo\": \"https://github.com/CaptainGreenskin/infra-guide.git\",\n  \"path\": \"dist/labs/delivery-systems/gitops-app\",\n  \"v1\": \"fb18c80ebda55f22180f7cd9a19360cb9e739202\",\n  \"config_only_v2\": \"872b300361e5a4ad9339d775c9e3310e60466fe1\",\n  \"rollout_v2\": \"703f38b1a3e29e66212595735fc54af02a694050\"\n}\n", "gitops_reconcile.py": "\"\"\"Actual Argo CD Core + kind, three immutable public revisions, independent HTTP version oracle.\"\"\"\nimport argparse\nimport hashlib\nimport json\nimport os\nfrom pathlib import Path\nimport subprocess\nimport tempfile\nimport time\nimport urllib.request\nimport uuid\n\nNODE_IMAGE = 'kindest/node:v1.35.8@sha256:07b2536e30b803ed61d1677a79df6115f798ce64c80f9e22f6ed45afd09323c0'\nARGO_VERSION = 'v3.6.1'\nARGO_URL = 'https://raw.githubusercontent.com/argoproj/argo-cd/' + ARGO_VERSION + '/manifests/core-install.yaml'\n\n\ndef command(*parts, data=None, check=True, timeout=240):\n    r = subprocess.run(parts, input=data, text=True, capture_output=True, timeout=timeout)\n    if check and r.returncode:\n        raise RuntimeError(parts[0] + ': ' + r.stderr[-4500:])\n    return r\n\n\ndef main():\n    ap = argparse.ArgumentParser()\n    ap.add_argument('--output', type=Path, default=Path('gitops-record.json'))\n    args = ap.parse_args()\n    sources = json.loads(Path(__file__).with_name('gitops-revisions.json').read_text())\n    assert not os.environ.get('DOCKER_HOST')\n    endpoint = json.loads(command('docker', 'context', 'inspect').stdout)[0]['Endpoints']['docker']['Host']\n    assert endpoint.startswith('unix://'), 'Only a local Docker context is accepted'\n    name = 'infra-gitops-' + uuid.uuid4().hex[:10]\n    assert name not in command('kind', 'get', 'clusters').stdout.splitlines()\n    records = {}\n    with tempfile.TemporaryDirectory(prefix='infra-gitops-') as tmp:\n        root = Path(tmp)\n        kubeconfig = root / 'kubeconfig'\n\n        def k(*parts, data=None, check=True):\n            return command('kubectl', '--kubeconfig', str(kubeconfig), '--context', 'kind-' + name,\n                           '--request-timeout=30s', *parts, data=data, check=check)\n\n        def get(kind, obj, ns='guide-demo'):\n            return json.loads(k('get', kind, obj, '-n', ns, '-o', 'json').stdout)\n\n        def apply(obj):\n            return k('apply', '-f', '-', data=json.dumps(obj))\n\n        def exists(kind, obj):\n            return bool(k('get', kind, obj, '-n', 'guide-demo', '--ignore-not-found', '-o', 'name').stdout.strip())\n\n        def patch_app(patch):\n            k('patch', 'application', 'guide', '-n', 'argocd', '--type=merge', '-p', json.dumps(patch))\n            k('annotate', 'application', 'guide', '-n', 'argocd', 'argocd.argoproj.io/refresh=hard', '--overwrite')\n\n        def wait(label, predicate, timeout=150):\n            deadline = time.monotonic() + timeout\n            last = None\n            while time.monotonic() < deadline:\n                try:\n                    last = predicate()\n                    if last:\n                        return last\n                except (RuntimeError, KeyError, IndexError):\n                    pass\n                time.sleep(1)\n            raise AssertionError(label + ': condition not reached; last=' + str(last))\n\n        def app_status():\n            app = get('application', 'guide', 'argocd')\n            st = app.get('status', {})\n            return {'sync': st.get('sync', {}).get('status'), 'revision': st.get('sync', {}).get('revision'),\n                    'health': st.get('health', {}).get('status'),\n                    'operation': st.get('operationState', {}).get('phase'),\n                    'conditions': st.get('conditions', [])}\n\n        def synced(revision):\n            st = app_status()\n            return st if st['revision'] == revision and st['sync'] == 'Synced' and st['health'] == 'Healthy' else False\n\n        def active_pods():\n            items = json.loads(k('get', 'pods', '-n', 'guide-demo', '-l', 'app=guide-web', '-o', 'json').stdout)['items']\n            return [p for p in items if not p['metadata'].get('deletionTimestamp')]\n\n        def one_ready_pod():\n            pods = active_pods()\n            if len(pods) != 1:\n                return False\n            p = pods[0]\n            if not any(c['type'] == 'Ready' and c['status'] == 'True' for c in p.get('status', {}).get('conditions', [])):\n                return False\n            return {'name': p['metadata']['name'], 'uid': p['metadata']['uid']}\n\n        def response():\n            pod = wait('single ready application pod', one_ready_pod)\n            script = 'import json,urllib.request; print(urllib.request.urlopen(\"http://guide-web:8080/version\",timeout=3).read().decode())'\n            body = json.loads(k('exec', '-n', 'guide-demo', pod['name'], '--', 'python', '-c', script).stdout)\n            return {'http': body, 'pod': pod, 'desired_config': get('configmap', 'guide-version')['data']['version']}\n\n        try:\n            command('kind', 'create', 'cluster', '--name', name, '--kubeconfig', str(kubeconfig),\n                    '--image', NODE_IMAGE, '--wait', '150s', timeout=400)\n            for ns in ('argocd', 'guide-demo'):\n                apply({'apiVersion': 'v1', 'kind': 'Namespace', 'metadata': {'name': ns}})\n            install = urllib.request.urlopen(ARGO_URL, timeout=45).read()\n            install_path = root / 'argocd-core.yaml'\n            install_path.write_bytes(install)\n            # Fresh, owned cluster: create avoids oversized last-applied annotations on CRDs.\n            k('create', '-n', 'argocd', '-f', str(install_path))\n            k('rollout', 'status', 'deployment/argocd-repo-server', '-n', 'argocd', '--timeout=180s')\n            project = {'apiVersion': 'argoproj.io/v1alpha1', 'kind': 'AppProject',\n                       'metadata': {'name': 'guide-scope', 'namespace': 'argocd'},\n                       'spec': {'sourceRepos': [sources['repo']],\n                                'destinations': [{'server': 'https://kubernetes.default.svc', 'namespace': 'guide-demo'}],\n                                'clusterResourceWhitelist': [], 'namespaceResourceWhitelist': [\n                                    {'group': '', 'kind': 'ConfigMap'}, {'group': '', 'kind': 'Service'},\n                                    {'group': 'apps', 'kind': 'Deployment'}]}}\n            apply(project)\n            apply({'apiVersion': 'v1', 'kind': 'ConfigMap', 'metadata': {'name': 'unmanaged', 'namespace': 'guide-demo'}, 'data': {'owner': 'outside-this-application'}})\n            apply({'apiVersion': 'argoproj.io/v1alpha1', 'kind': 'Application',\n                   'metadata': {'name': 'guide', 'namespace': 'argocd'},\n                   'spec': {'project': 'guide-scope', 'source': {'repoURL': sources['repo'], 'path': sources['path'],\n                             'targetRevision': sources['v1'], 'directory': {}},\n                            'destination': {'server': 'https://kubernetes.default.svc', 'namespace': 'guide-demo'},\n                            'syncPolicy': {'automated': {'enabled': True, 'selfHeal': False, 'prune': False}}}})\n            initial = wait('v1 synced and healthy', lambda: synced(sources['v1']), timeout=240)\n            records['v1'] = {'status': initial, **response()}\n            assert records['v1']['http']['version'] == 'v1'\n            k('scale', 'deployment/guide-web', '-n', 'guide-demo', '--replicas=2')\n            k('rollout', 'status', 'deployment/guide-web', '-n', 'guide-demo', '--timeout=90s')\n            k('annotate', 'application', 'guide', '-n', 'argocd', 'argocd.argoproj.io/refresh=hard', '--overwrite')\n            wait('drift detected', lambda: app_status()['sync'] == 'OutOfSync')\n            records['self_heal_off'] = {'status': app_status(), 'live_replicas': get('deployment', 'guide-web')['spec']['replicas']}\n            assert records['self_heal_off']['live_replicas'] == 2\n            patch_app({'spec': {'syncPolicy': {'automated': {'selfHeal': True}}}})\n            wait('self healed v1', lambda: synced(sources['v1']))\n            before_v2 = response()\n            records['self_heal_on'] = {'status': app_status(), 'live_replicas': get('deployment', 'guide-web')['spec']['replicas'], **before_v2}\n            assert records['self_heal_on']['live_replicas'] == 1\n            patch_app({'spec': {'source': {'targetRevision': sources['config_only_v2']}}})\n\n            def v2_applied():\n                st = app_status()\n                return st if (st['revision'] == sources['config_only_v2'] and st['operation'] == 'Succeeded'\n                              and get('configmap', 'guide-version')['data']['version'] == 'v2') else False\n            wait('v2 manifests applied, pruning disabled', v2_applied)\n            records['prune_off'] = {'status': app_status(), 'retired_exists': exists('configmap', 'guide-retired'),\n                                    'unmanaged_exists': exists('configmap', 'unmanaged')}\n            assert records['prune_off']['retired_exists'] and records['prune_off']['unmanaged_exists']\n            patch_app({'spec': {'syncPolicy': {'automated': {'prune': True}}}})\n            wait('managed retired ConfigMap pruned', lambda: not exists('configmap', 'guide-retired'))\n            wait('v2 fully synced and healthy', lambda: synced(sources['config_only_v2']))\n            v2 = response()\n            records['v2_synced_but_old_business'] = {'status': app_status(), **v2,\n                'retired_exists': exists('configmap', 'guide-retired'), 'unmanaged_exists': exists('configmap', 'unmanaged'),\n                'business_oracle_passed': v2['http']['version'] == 'v2'}\n            assert v2['desired_config'] == 'v2' and v2['http']['version'] == 'v1'\n            assert v2['pod']['uid'] == before_v2['pod']['uid']\n            assert records['v2_synced_but_old_business']['unmanaged_exists']\n            patch_app({'spec': {'source': {'targetRevision': sources['rollout_v2']}}})\n            wait('new template v2', lambda: synced(sources['rollout_v2']))\n            v3 = response()\n            assert v3['http']['version'] == 'v2' and v3['pod']['uid'] != v2['pod']['uid']\n            records['v3_new_pod'] = {'status': app_status(), **v3, 'business_oracle_passed': True}\n            # Change desired revision; this is not the disabled-with-auto-sync rollback API.\n            patch_app({'spec': {'source': {'targetRevision': sources['v1']}}})\n            wait('return desired revision to v1', lambda: synced(sources['v1']))\n            back = response()\n            assert back['http']['version'] == 'v1' and exists('configmap', 'guide-retired')\n            records['return_to_v1'] = {'status': app_status(), **back, 'managed_config_recreated': True}\n            report = {'schema': 1, 'status': 'passed', 'kind': command('kind', 'version').stdout.strip(),\n                      'kubernetes': json.loads(k('version', '-o', 'json').stdout)['serverVersion']['gitVersion'],\n                      'argo_version': ARGO_VERSION, 'argo_manifest_url': ARGO_URL,\n                      'argo_manifest_sha256': hashlib.sha256(install).hexdigest(), 'sources': sources,\n                      'records': records, 'source_sha256': hashlib.sha256(Path(__file__).read_bytes()).hexdigest(),\n                      'revision_file_sha256': hashlib.sha256(Path(__file__).with_name('gitops-revisions.json').read_bytes()).hexdigest(),\n                      'scope': 'real Argo CD Core Git fetch/reconcile and HTTP in a single-host kind cluster; not cloud/prod/physical multi-node'}\n            args.output.parent.mkdir(parents=True, exist_ok=True)\n            args.output.write_text(json.dumps(report, indent=2) + '\\n')\n            print(json.dumps(report))\n        except Exception:\n            if kubeconfig.exists():\n                status = k('get', 'application', 'guide', '-n', 'argocd', '-o', 'json', check=False)\n                if status.returncode == 0:\n                    # Only application status; never write kubeconfig or Secret data to artifacts.\n                    failure = json.loads(status.stdout).get('status', {})\n                    args.output.parent.mkdir(parents=True, exist_ok=True)\n                    args.output.with_suffix('.failure.json').write_text(json.dumps(failure, indent=2))\n            raise\n        finally:\n            command('kind', 'delete', 'cluster', '--name', name, check=False)\n\n\nif __name__ == '__main__':\n    main()\n", "mq_client.py": "\"\"\"Real AMQP 0-9-1 client. Runs inside the owned internal Docker network.\"\"\"\nimport argparse\nimport hashlib\nimport json\nimport os\nfrom pathlib import Path\nimport signal\nimport sqlite3\nimport subprocess\nimport sys\nimport time\n\nimport pika\n\n\ndef connect():\n    return pika.BlockingConnection(pika.ConnectionParameters(\n        os.environ['GUIDE_BROKER'], credentials=pika.PlainCredentials('guide', 'public-disposable-lab'),\n        heartbeat=30, blocked_connection_timeout=10, socket_timeout=10))\n\n\ndef declare(ch, queue):\n    return ch.queue_declare(queue=queue, durable=True, arguments={'x-queue-type': 'classic'})\n\n\ndef publish(ch, queue, message='transport-1', op='report-27', amount=37, mandatory=True):\n    body = json.dumps({'op': op, 'amount': amount}, sort_keys=True).encode()\n    ch.basic_publish(exchange='', routing_key=queue, body=body, mandatory=mandatory,\n                     properties=pika.BasicProperties(delivery_mode=2, message_id=message))\n\n\ndef ledger(path, body=None):\n    with sqlite3.connect(path) as con:\n        con.execute('CREATE TABLE IF NOT EXISTS effects(op TEXT PRIMARY KEY, amount INTEGER NOT NULL, fingerprint TEXT NOT NULL)')\n        duplicate = None\n        if body is not None:\n            data = json.loads(body)\n            digest = hashlib.sha256(json.dumps(data, sort_keys=True).encode()).hexdigest()\n            con.execute('BEGIN IMMEDIATE')\n            row = con.execute('SELECT amount,fingerprint FROM effects WHERE op=?', (data['op'],)).fetchone()\n            if row:\n                assert row == (data['amount'], digest), 'same operation has conflicting parameters'\n                duplicate = True\n            else:\n                con.execute('INSERT INTO effects VALUES(?,?,?)', (data['op'], data['amount'], digest))\n                duplicate = False\n        rows = con.execute('SELECT op,amount FROM effects ORDER BY op').fetchall()\n    return {'effects': len(rows), 'total': sum(r[1] for r in rows), 'operations': rows, 'duplicate': duplicate}\n\n\ndef receive(ch, queue):\n    deadline = time.monotonic() + 10\n    while time.monotonic() < deadline:\n        method, props, body = ch.basic_get(queue, auto_ack=False)\n        if method:\n            return method, props, body\n        time.sleep(.05)\n    raise TimeoutError('message did not become ready: ' + queue)\n\n\ndef worker(queue, path, early_ack):\n    conn = connect()\n    ch = conn.channel()\n    method, props, body = receive(ch, queue)\n    if early_ack:\n        ch.basic_ack(method.delivery_tag)\n        declare(ch, queue)  # same-channel RPC is a barrier after the asynchronous ACK\n    else:\n        ledger(path, body)\n    print(json.dumps({'message_id': props.message_id, 'delivery_tag': method.delivery_tag}), flush=True)\n    sys.stdin.readline()  # parent kills this process, before the missing commit/ACK\n\n\ndef pump(conn, predicate):\n    deadline = time.monotonic() + 10\n    while not predicate():\n        assert time.monotonic() < deadline\n        conn.process_data_events(time_limit=.1)\n\n\ndef main():\n    ap = argparse.ArgumentParser()\n    ap.add_argument('--worker')\n    ap.add_argument('--db', default='/work/effects.sqlite')\n    ap.add_argument('--early-ack', action='store_true')\n    ap.add_argument('--phase', choices=['prepare', 'after-restart'], default='prepare')\n    args = ap.parse_args()\n    if args.worker:\n        worker(args.worker, args.db, args.early_ack)\n        return\n    conn = connect()\n    ch = conn.channel()\n    version = conn._impl.server_properties['version']\n    if args.phase == 'after-restart':\n        declare(ch, 'guide_restart')\n        method, props, body = receive(ch, 'guide_restart')\n        assert props.delivery_mode == 2 and json.loads(body) == {'op': 'survive-restart', 'amount': 7}\n        ch.basic_ack(method.delivery_tag)\n        ready = declare(ch, 'guide_restart').method.message_count\n        assert ready == 0\n        print(json.dumps({'broker_version': version, 'persistent_body': json.loads(body), 'ready_after_ack': ready,\n                          'scope': 'same durable single-node broker volume after container restart, not power loss or HA'}))\n        conn.close()\n        return\n    rows = {}\n    ch.confirm_delivery()\n    try:\n        publish(ch, 'not-declared', mandatory=True)\n        raise AssertionError('mandatory unroutable publish was not returned')\n    except pika.exceptions.UnroutableError:\n        rows['mandatory'] = {'unroutable_detected': True}\n    # Publisher confirm by itself does not imply that any consumer/queue received it.\n    publish(ch, 'not-declared', mandatory=False)\n    probe = conn.channel()\n    try:\n        probe.queue_declare('not-declared', passive=True)\n        raise AssertionError('unexpected queue')\n    except pika.exceptions.ChannelClosedByBroker as exc:\n        assert exc.reply_code == 404\n        rows['confirm_without_route'] = {'publish_returned_normally': True, 'queue_exists': False}\n    declare(ch, 'guide_effect')\n    publish(ch, 'guide_effect')\n    proc = subprocess.Popen([sys.executable, '-B', __file__, '--worker', 'guide_effect', '--db', args.db],\n                            stdin=subprocess.PIPE, stdout=subprocess.PIPE, stderr=subprocess.PIPE, text=True)\n    try:\n        first = json.loads(proc.stdout.readline())\n        at_crash = ledger(args.db)\n        assert at_crash['effects'] == 1 and at_crash['total'] == 37\n        proc.kill()\n        proc.wait(timeout=5)\n        assert proc.returncode == -signal.SIGKILL\n        method, props, body = receive(ch, 'guide_effect')\n        assert method.redelivered and props.message_id == first['message_id']\n        recovered = ledger(args.db, body)\n        assert recovered['duplicate'] and recovered['effects'] == 1 and recovered['total'] == 37\n        ch.basic_ack(method.delivery_tag)\n        publish(ch, 'guide_effect', message='new-transport-same-business')\n        again, republished, body = receive(ch, 'guide_effect')\n        again_state = ledger(args.db, body)\n        assert again_state['duplicate'] and again_state['effects'] == 1\n        ch.basic_ack(again.delivery_tag)\n        assert declare(ch, 'guide_effect').method.message_count == 0\n        rows['effect_before_ack_crash'] = {'kill_exit': proc.returncode, 'first_delivery': first,\n            'redelivery': {'message_id': props.message_id, 'delivery_tag': method.delivery_tag, 'redelivered': method.redelivered},\n            'republished_message_id': republished.message_id, 'at_crash': at_crash, 'recovered': recovered, 'after_republish': again_state}\n    finally:\n        if proc.poll() is None:\n            proc.kill()\n            proc.wait(timeout=5)\n    declare(ch, 'guide_early_ack')\n    publish(ch, 'guide_early_ack', op='early-ack', amount=11)\n    negative_db = str(Path(args.db).with_name('early-ack.sqlite'))\n    proc = subprocess.Popen([sys.executable, '-B', __file__, '--worker', 'guide_early_ack', '--db', negative_db, '--early-ack'],\n                            stdin=subprocess.PIPE, stdout=subprocess.PIPE, stderr=subprocess.PIPE, text=True)\n    try:\n        first = json.loads(proc.stdout.readline())\n        proc.kill()\n        proc.wait(timeout=5)\n        remaining = declare(ch, 'guide_early_ack').method.message_count\n        effects = ledger(negative_db)\n        assert remaining == 0 and effects['effects'] == 0\n        rows['ack_before_effect_negative'] = {'kill_exit': proc.returncode, 'ready_messages': remaining,\n                                              'business': effects, 'business_oracle_passed': False}\n    finally:\n        if proc.poll() is None:\n            proc.kill()\n            proc.wait(timeout=5)\n    declare(ch, 'guide_push')\n    for i in range(2):\n        publish(ch, 'guide_push', message='push-' + str(i))\n    consumer = conn.channel()\n    consumer.basic_qos(prefetch_count=1)\n    deliveries = []\n    tag = consumer.basic_consume('guide_push', lambda _ch, m, _p, _b: deliveries.append(m.delivery_tag), auto_ack=False)\n    pump(conn, lambda: len(deliveries) == 1)\n    ready_before_ack = declare(ch, 'guide_push').method.message_count\n    assert ready_before_ack == 1 and len(deliveries) == 1\n    consumer.basic_ack(deliveries[0])\n    pump(conn, lambda: len(deliveries) == 2)\n    consumer.basic_ack(deliveries[1])\n    consumer.basic_cancel(tag)\n    rows['prefetch_push'] = {'prefetch': 1, 'delivered_before_ack': 1, 'ready_before_ack': ready_before_ack,\n                             'delivered_after_ack': len(deliveries), 'ready_after_all_ack': declare(ch, 'guide_push').method.message_count}\n    declare(ch, 'guide_pull')\n    for i in range(2):\n        publish(ch, 'guide_pull', message='pull-' + str(i))\n    pull = conn.channel()\n    pull.basic_qos(prefetch_count=1)\n    m1, _, _ = receive(pull, 'guide_pull')\n    m2, _, _ = receive(pull, 'guide_pull')\n    assert m2.delivery_tag > m1.delivery_tag\n    rows['prefetch_get_exception'] = {'prefetch': 1, 'unacked_get_deliveries': 2,\n                                     'ready_before_ack': declare(ch, 'guide_pull').method.message_count}\n    pull.basic_ack(m1.delivery_tag)\n    pull.basic_ack(m2.delivery_tag)\n    pull.close()\n    declare(ch, 'guide_tags')\n    publish(ch, 'guide_tags', message='channel-scope')\n    right, wrong = conn.channel(), conn.channel()\n    original, _, _ = receive(right, 'guide_tags')\n    try:\n        wrong.basic_ack(original.delivery_tag)\n        declare(wrong, 'guide_tags')\n        raise AssertionError('wrong channel ACK was accepted')\n    except pika.exceptions.ChannelClosedByBroker as exc:\n        assert exc.reply_code == 406 and 'unknown delivery tag' in exc.reply_text.lower()\n        rows['wrong_channel_ack'] = {'reply_code': exc.reply_code, 'wrong_channel_closed': wrong.is_closed,\n                                      'right_channel_open': right.is_open}\n    right.close()\n    repeated, prop, _ = receive(ch, 'guide_tags')\n    assert repeated.redelivered and prop.message_id == 'channel-scope'\n    ch.basic_ack(repeated.delivery_tag)\n    declare(ch, 'guide_restart')\n    publish(ch, 'guide_restart', op='survive-restart', amount=7)\n    pending = declare(ch, 'guide_restart').method.message_count\n    assert pending == 1\n    report = {'schema': 1, 'status': 'passed', 'broker_version': version, 'pika_version': pika.__version__,\n              'cases': rows, 'durable_before_restart': {'ready_messages': pending, 'delivery_mode': 2},\n              'source_sha256': hashlib.sha256(Path(__file__).read_bytes()).hexdigest(),\n              'scope': 'actual AMQP broker and SQLite consumer effects, own internal Docker network; not SQS/Lambda/HA'}\n    conn.close()\n    print(json.dumps(report))\n\n\nif __name__ == '__main__':\n    main()\n", "mq_delivery.py": "\"\"\"Own broker/client/network/volume only. No host ports or cloud resources.\"\"\"\nimport argparse\nimport hashlib\nimport json\nimport os\nfrom pathlib import Path\nimport subprocess\nimport tempfile\nimport time\nimport uuid\n\n\ndef run(*parts, check=True, timeout=240):\n    r = subprocess.run(parts, text=True, capture_output=True, timeout=timeout)\n    if check and r.returncode:\n        raise RuntimeError(parts[0] + ': ' + (r.stdout + r.stderr)[-5000:])\n    return r\n\n\ndef wait_broker(name):\n    deadline = time.monotonic() + 90\n    last_error = ''\n    while time.monotonic() < deadline:\n        r = run('docker', 'exec', '--user', 'rabbitmq', name, 'rabbitmq-diagnostics', '-q', 'check_port_connectivity', check=False, timeout=20)\n        if r.returncode == 0:\n            return\n        last_error = (r.stdout + r.stderr)[-1500:]\n        state = json.loads(run('docker', 'inspect', '--format', '{{json .State}}', name).stdout)\n        if not state['Running']:\n            break\n        time.sleep(1)\n    logs = run('docker', 'logs', '--tail', '40', name, check=False)\n    raise TimeoutError('owned RabbitMQ not ready: ' + last_error + '\\n' + logs.stdout + logs.stderr)\n\n\ndef main():\n    ap = argparse.ArgumentParser()\n    ap.add_argument('--output', type=Path, default=Path('mq-record.json'))\n    args = ap.parse_args()\n    assert not os.environ.get('DOCKER_HOST')\n    endpoint = json.loads(run('docker', 'context', 'inspect').stdout)[0]['Endpoints']['docker']['Host']\n    assert endpoint.startswith('unix://')\n    suffix = uuid.uuid4().hex[:12]\n    broker, client, network, volume, image = ['infra-mq-' + n + '-' + suffix for n in ('broker', 'client', 'net', 'data', 'image')]\n    folder = Path(__file__).resolve().parent\n    try:\n        run('docker', 'build', '-f', str(folder / 'Dockerfile.mq-client'), '-t', image, str(folder))\n        run('docker', 'pull', 'rabbitmq:4.4.0')\n        broker_image = json.loads(run('docker', 'image', 'inspect', 'rabbitmq:4.4.0').stdout)[0]['RepoDigests'][0]\n        run('docker', 'network', 'create', '--internal', network)\n        run('docker', 'volume', 'create', volume)\n        run('docker', 'run', '-d', '--name', broker, '--network', network, '--network-alias', 'broker',\n            '--cpus', '1', '--memory', '512m', '--pids-limit', '128',\n            '-e', 'RABBITMQ_DEFAULT_USER=guide', '-e', 'RABBITMQ_DEFAULT_PASS=public-disposable-lab',\n            '-e', 'RABBITMQ_SERVER_ADDITIONAL_ERL_ARGS=+S 2:2',\n            '-e', 'RABBITMQ_CTL_ERL_ARGS=+S 1:1 +SDcpu 1 +SDio 1', '-v', volume + ':/var/lib/rabbitmq', broker_image)\n        wait_broker(broker)\n        run('docker', 'run', '-d', '--name', client, '--network', network, '--memory', '160m', '--pids-limit', '64',\n            '-e', 'GUIDE_BROKER=broker', image)\n        first = json.loads(run('docker', 'exec', client, 'python', '-B', '/work/mq_client.py').stdout)\n        assert first['status'] == 'passed'\n        run('docker', 'restart', broker)\n        wait_broker(broker)\n        restarted = json.loads(run('docker', 'exec', client, 'python', '-B', '/work/mq_client.py', '--phase', 'after-restart').stdout)\n        report = {'schema': 1, 'status': 'passed', 'broker_image': broker_image,\n                  'execution': first, 'after_broker_restart': restarted,\n                  'source_sha256': {p.name: hashlib.sha256(p.read_bytes()).hexdigest()\n                                    for p in (Path(__file__), folder / 'mq_client.py', folder / 'Dockerfile.mq-client')},\n                  'scope': 'actual isolated RabbitMQ, manual ACK and publisher confirms, one-node durable restart; no SQS/Lambda/HA/cloud claim'}\n        args.output.parent.mkdir(parents=True, exist_ok=True)\n        args.output.write_text(json.dumps(report, indent=2) + '\\n')\n        print(json.dumps(report))\n    finally:\n        for name in (client, broker):\n            run('docker', 'rm', '-f', name, check=False)\n        run('docker', 'volume', 'rm', volume, check=False)\n        run('docker', 'network', 'rm', network, check=False)\n        run('docker', 'image', 'rm', image, check=False)\n\n\nif __name__ == '__main__':\n    main()\n", "terraform_state.py": "\"\"\"Real Terraform local backend + official local_file provider, only in an owned temp directory.\"\"\"\nimport argparse\nimport hashlib\nimport json\nimport os\nfrom pathlib import Path\nimport shlex\nimport signal\nimport subprocess\nimport sys\nimport tempfile\nimport time\n\n\ndef main():\n    ap = argparse.ArgumentParser()\n    ap.add_argument('--output', type=Path, default=Path('terraform-record.json'))\n    ap.add_argument('--hold', nargs=2)\n    args = ap.parse_args()\n    if args.hold:\n        ready, release = map(Path, args.hold)\n        ready.write_text('apply holds local state lock\\n')\n        deadline = time.monotonic() + 25\n        while not release.exists():\n            if time.monotonic() > deadline:\n                raise TimeoutError('parent did not release the owned provisioner')\n            time.sleep(.05)\n        return\n    assert os.name == 'posix'\n    with tempfile.TemporaryDirectory(prefix='infra-tf-state-') as tmp:\n        root = Path(tmp)\n        ready, release = root / 'ready', root / 'release'\n        config = {'terraform': {'required_version': '= 1.13.0', 'required_providers': {\n            'local': {'source': 'hashicorp/local', 'version': '= 2.5.3'}}},\n            'variable': {'content': {'type': 'string', 'default': 'alpha'}},\n            'resource': {\n                'local_file': {'managed': {'filename': '${path.module}/managed.txt', 'content': '${var.content}',\n                                          'file_permission': '0600', 'directory_permission': '0700'}},\n                'terraform_data': {'gate': {'input': 'one-controlled-apply', 'depends_on': ['local_file.managed'],\n                    'provisioner': [{'local-exec': {'command': shlex.join([\n                        sys.executable, str(Path(__file__).resolve()), '--hold', str(ready), str(release)])}}]}}}}\n        (root / 'main.tf.json').write_text(json.dumps(config, indent=2))\n        (root / 'terraform.rc').write_text('disable_checkpoint = true\\n')\n        env = {**os.environ, 'TF_IN_AUTOMATION': '1', 'TF_INPUT': '0', 'TF_CLI_CONFIG_FILE': str(root / 'terraform.rc')}\n        prefix = ['terraform', '-chdir=' + str(root)]\n\n        def tf(*parts, expected=(0,)):\n            result = subprocess.run(prefix + list(parts), env=env, text=True, capture_output=True, timeout=120)\n            if result.returncode not in expected:\n                raise RuntimeError((result.stdout + result.stderr).replace(str(root), 'ROOT')[-6000:])\n            return result\n\n        def plan(name, *flags):\n            result = tf('plan', '-input=false', '-no-color', '-detailed-exitcode', '-out=' + name, *flags, expected=(0, 2))\n            body = json.loads(tf('show', '-json', name).stdout)\n            return result.returncode, body\n\n        def state():\n            r = json.loads(tf('state', 'pull').stdout)\n            return {'serial': r['serial'], 'lineage': r['lineage'],\n                    'resources': [{'address': p['type'] + '.' + p['name'],\n                                   'content': p['instances'][0]['attributes'].get('content')}\n                                  for p in r.get('resources', []) if p.get('instances')]}\n\n        def file_content():\n            return (root / 'managed.txt').read_text()\n\n        tf('init', '-input=false', '-no-color')\n        version = json.loads(tf('version', '-json').stdout)\n        assert version['terraform_version'] == '1.13.0'\n        assert version['provider_selections']['registry.terraform.io/hashicorp/local'] == '2.5.3'\n        writer = subprocess.Popen(prefix + ['apply', '-input=false', '-auto-approve', '-no-color', '-parallelism=1'],\n                                  env=env, stdout=subprocess.PIPE, stderr=subprocess.PIPE, text=True, start_new_session=True)\n        try:\n            deadline = time.monotonic() + 60\n            while not ready.exists():\n                if writer.poll() is not None:\n                    stdout, stderr = writer.communicate()\n                    raise RuntimeError(stdout + stderr)\n                assert time.monotonic() < deadline, 'apply never reached the controlled provisioner'\n                time.sleep(.1)\n            assert writer.poll() is None and file_content() == 'alpha'\n            lock_path = root / '.terraform.tfstate.lock.info'\n            lock = json.loads(lock_path.read_text())\n            blocked = tf('plan', '-input=false', '-no-color', '-lock-timeout=0s', expected=(1,))\n            assert 'Error acquiring the state lock' in blocked.stdout + blocked.stderr\n            assert writer.poll() is None\n            lock_record = {'second_exit': blocked.returncode, 'first_still_running': True,\n                           'lock_operation': lock['Operation'], 'file_during_apply': file_content()}\n        finally:\n            release.write_text('release\\n')\n            try:\n                stdout, stderr = writer.communicate(timeout=15)\n            except subprocess.TimeoutExpired:\n                os.killpg(writer.pid, signal.SIGTERM)\n                stdout, stderr = writer.communicate(timeout=10)\n        assert writer.returncode == 0, (stdout + stderr).replace(str(root), 'ROOT')\n        assert not lock_path.exists()\n        initial = state()\n        clean_code, _ = plan('clean.plan')\n        assert clean_code == 0 and file_content() == 'alpha'\n        (root / 'managed.txt').write_text('outside')\n        stale_code, stale_plan = plan('cached.plan', '-refresh=false')\n        assert stale_code == 0 and file_content() == 'outside'\n        before_refresh_state = state()\n        refresh_code, refresh_plan = plan('refresh.plan', '-refresh-only')\n        assert refresh_code == 2\n        drifts = [{'address': x['address'], 'actions': x['change']['actions']} for x in refresh_plan['resource_drift']]\n        assert {'address': 'local_file.managed', 'actions': ['delete']} in drifts\n        tf('apply', '-input=false', '-no-color', 'refresh.plan')\n        after_refresh_state = state()\n        assert file_content() == 'outside'\n        assert not any(r['address'] == 'local_file.managed' for r in after_refresh_state['resources'])\n        repair_code, repair_plan = plan('repair.plan')\n        actions = [{'address': x['address'], 'actions': x['change']['actions']} for x in repair_plan['resource_changes']]\n        assert repair_code == 2 and {'address': 'local_file.managed', 'actions': ['create']} in actions\n        tf('apply', '-input=false', '-no-color', 'repair.plan')\n        assert file_content() == 'alpha'\n        repaired_file = file_content()\n        repaired = state()\n        tf('workspace', 'new', 'blue')\n        tf('apply', '-input=false', '-auto-approve', '-no-color', '-var=content=alpha')\n        blue = state()\n        tf('workspace', 'new', 'green')\n        tf('apply', '-input=false', '-auto-approve', '-no-color', '-var=content=beta')\n        green = state()\n        assert file_content() == 'beta' and blue['lineage'] != green['lineage']\n        tf('workspace', 'select', 'blue')\n        workspace_cached_code, _ = plan('workspace-cached.plan', '-refresh=false', '-var=content=alpha')\n        workspace_fresh_code, _ = plan('workspace-fresh.plan', '-var=content=alpha')\n        assert workspace_cached_code == 0 and workspace_fresh_code == 2 and file_content() == 'beta'\n        report = {'schema': 1, 'status': 'passed', 'version': version, 'lock': lock_record,\n                  'initial': initial, 'external_edit': {'actual_file': 'outside', 'cached_plan_exit': stale_code,\n                    'cached_state': before_refresh_state},\n                  'refresh_only': {'plan_exit': refresh_code, 'drifts': drifts, 'state': after_refresh_state,\n                                   'actual_file_after_apply': 'outside'},\n                  'repair': {'actions': actions, 'actual_file': repaired_file, 'state': repaired},\n                  'workspaces': {'blue': blue, 'green': green, 'same_target': 'ROOT/managed.txt', 'actual_file': file_content(),\n                                 'blue_cached_plan_exit': workspace_cached_code, 'blue_fresh_plan_exit': workspace_fresh_code},\n                  'source_sha256': hashlib.sha256(Path(__file__).read_bytes()).hexdigest(),\n                  'provider_lock_sha256': hashlib.sha256((root / '.terraform.lock.hcl').read_bytes()).hexdigest(),\n                  'scope': 'actual Terraform local backend + official local_file; temp files only, not cloud provider/remote backend/HA'}\n        args.output.parent.mkdir(parents=True, exist_ok=True)\n        args.output.write_text(json.dumps(report, indent=2) + '\\n')\n        print(json.dumps(report))\n\n\nif __name__ == '__main__':\n    main()\n"};
